(()=>{const W='https://wa.me/212670779271',wa=(e,l)=>{e.href=W+'?text='+encodeURIComponent('Hello Tivione IPTV, I am interested in: '+l);e.target='_blank';e.rel='noopener'},esc=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function routes(){document.querySelectorAll('a').forEach(a=>{const x=a.textContent.trim().toLowerCase();if(x==='view plans')a.href='/pricing/';else if(x==='become a reseller'||x.includes('reseller packs'))a.href='/reseller/';else if(x==='need setup help'||x==='get setup help')a.href='/guides/';else if(x==='get app player')a.href='/apps/'})}function reseller(){if(location.pathname!=='/reseller/'||document.querySelector('#reseller-features'))return;document.querySelector('#reseller-specs')?.remove();const s=document.createElement('section');s.id='reseller-features';s.innerHTML='<div class="wrap"><div class="section-head"><span class="eyebrow">Reseller plan features</span><h2>Everything included with your reseller access</h2></div><div class="card"><ul class="checklist"><li>Instant activation</li><li>Up to +22,000 channels</li><li>Up to +88,000 VODs, Series</li><li>0.1 Credit = 1 Month</li><li>0.3 Credit = 3 Months</li><li>0.5 Credit = 6 Months</li><li>1 Credit = 12 Months</li><li>24/7 support</li><li>Full API access</li><li>Own domain / white-label support</li></ul><a class="btn" data-wa>Start reseller plan</a></div></div>';const m=document.querySelector('main'),o=m?.querySelector('.callout');m?.insertBefore(s,o||null);wa(s.querySelector('[data-wa]'),'Reseller plan')}const posts=['IPTV setup guide for beginners','How to choose an IPTV player','Firestick player installation guide','Smart TV streaming setup guide','Android IPTV player guide','TiviMate configuration guide','IPTV Smarters setup guide','IBO Player Pro setup guide','How to improve streaming stability','Global EPG guide','Understanding IPTV playlists','Xtream Codes login guide'];const paragraphs=['Start with a compatible device and an up-to-date player. Before adding account information, make sure your device has a stable internet connection and enough storage for the app. A wired connection can reduce local Wi-Fi interference, while a strong 5 GHz network can also perform well.','Select the connection method supplied with your account. Many players accept a playlist address or an Xtream-style login made of a server address, username and password. Enter each detail exactly as provided and keep account information private.','When the app loads, allow time for the available categories and programme guide to populate. If a category is slow to appear, check player settings, restart the app and confirm your home connection is working normally. Avoid downloads on the same network while testing playback.','For smoother viewing, keep the app and device system current, then choose playback quality suited to your connection. High-resolution streams need more stable bandwidth. If a problem continues, support can investigate faster when you include your device, player, error details and a screenshot.','This guide helps you make informed setup choices. Availability can depend on device capability, network conditions and catalogue updates. For a specific player or account question, contact support and include the exact step where assistance is required.','With the right player, a stable home network and clear setup details, the process is simple. Review the relevant device guide, save this page for later and use support when you need one-to-one assistance.'];function blog(){if(location.pathname!=='/blog/')return;const m=document.querySelector('main'),post=new URLSearchParams(location.search).get('post');if(!m)return;if(post){m.innerHTML='<section class="page-hero"><article class="wrap article blog-article"><span class="eyebrow">Tivione IPTV guide</span><h1>'+esc(post)+'</h1><p class="lead">A practical, device-first guide to preparing your player, checking your network and getting support.</p>'+paragraphs.map(p=>'<p>'+p+'</p>').join('')+'<div class="actions"><a class="btn" data-wa>Get setup support</a><a class="btn ghost" href="/blog/">Back to blog</a></div></article></section>';wa(m.querySelector('[data-wa]'),'Blog setup support');return}m.innerHTML='<section class="page-hero"><div class="wrap"><span class="eyebrow">Tivione IPTV blog</span><h1>Setup, player and streaming guides</h1><p class="lead">Clear guides for choosing a player, configuring your device and improving home streaming.</p></div></section><section><div class="wrap"><div class="grid three">'+posts.map((p,i)=>'<article class="card blog-card"><img src="/assets/network-background.png" alt="'+esc(p)+'" loading="lazy"><span class="blog-meta">Setup guide · '+(i+1)+'</span><h3>'+esc(p)+'</h3><p>Practical steps, player recommendations and troubleshooting notes for Tivione IPTV customers.</p><a class="btn small" href="/blog/?post='+encodeURIComponent(p)+'">Read more</a></article>').join('')+'</div></div></section>'}function run(){document.querySelector('#advanced-faq')?.remove();routes();reseller();blog()}setTimeout(run,300);document.addEventListener('DOMContentLoaded',run)})();
